    "content": "\u201E\u10D7\u10E3 \u10D2\u10D8\u10DC\u10D3\u10D0 \u10E8\u10D4\u10D8\u10EA\u10D5\u10D0\u10DA\u10DD\u10E1 \u10E8\u10D4\u10D3\u10D4\u10D2\u10D8, \u10E8\u10D4\u10EA\u10D5\u10D0\u10DA\u10D4 \u10DB\u10DD\u10E5\u10DB\u10D4\u10D3\u10D4\u10D1\u10D0.\u201C",
