    "content": "\u10E8\u10D4\u10EE\u10D5\u10D4\u10D3\u10E0\u10D0\u10DB\u10D3\u10D4 5 \u10EC\u10E3\u10D7\u10D8\u10D7 \u10D0\u10D3\u10E0\u10D4 \u10E8\u10D4\u10D0\u10DB\u10DD\u10EC\u10DB\u10D4 \u10D1\u10DB\u10E3\u10DA\u10D8, \u10EE\u10DB\u10D0 \u10D3\u10D0 \u10D9\u10D0\u10DB\u10D4\u10E0\u10D0.",
