    "content": "\u10D7\u10E3 \u10E0\u10D0\u10DB\u10D4 \u10EE\u10E8\u10D8\u10E0\u10D0\u10D3 \u10D2\u10ED\u10D8\u10E0\u10D3\u10D4\u10D1\u10D0, \u10E0\u10D0\u10DB\u10D3\u10D4\u10DC\u10D8\u10DB\u10D4 \u10EA\u10D0\u10DA\u10D8 \u10EC\u10D8\u10DC\u10D0\u10E1\u10EC\u10D0\u10E0 \u10E8\u10D4\u10D8\u10EB\u10D8\u10DC\u10D4 \u2014 \u10DB\u10E3\u10D3\u10DB\u10D8\u10D5 \u10EB\u10D4\u10D1\u10DC\u10D0\u10E1\u10D0 \u10D3\u10D0 \u10E1\u10D8\u10E0\u10D1\u10D8\u10DA\u10E1 \u10D0\u10D8\u10E0\u10D8\u10D3\u10D4\u10D1.",
