    "content": "\u201E\u10EA\u10DD\u10D3\u10DC\u10D0 \u10EB\u10D0\u10DA\u10D0\u10D0.\u201C \u2014 \u10E4\u10E0\u10D4\u10DC\u10E1\u10D8\u10E1 \u10D1\u10D4\u10D9\u10DD\u10DC\u10D8",
