    "category": "\u10EA\u10D8\u10E2\u10D0\u10E2\u10D0",
    "content": "\u201E\u10DB\u10D0\u10E0\u10EA\u10EE\u10D8 \u10DB\u10EE\u10DD\u10DA\u10DD\u10D3 \u10DB\u10D0\u10E8\u10D8\u10DC \u10D0\u10E0\u10D8\u10E1 \u10E1\u10D0\u10D1\u10DD\u10DA\u10DD\u10DD, \u10E0\u10DD\u10EA\u10D0 \u10D3\u10D0\u10DC\u10D4\u10D1\u10D3\u10D4\u10D1\u10D8.\u201C",
