    "content": "\u201E\u10E1\u10D8\u10E9\u10E3\u10DB\u10D4 \u10EE\u10E8\u10D8\u10E0\u10D0\u10D3 \u10E1\u10D0\u10E3\u10D9\u10D4\u10D7\u10D4\u10E1\u10DD \u10DE\u10D0\u10E1\u10E3\u10EE\u10D8\u10D0.\u201C",
