    "content": "\u201E\u10D0\u10D3\u10D0\u10DB\u10D8\u10D0\u10DC\u10D8 \u10D8\u10DB\u10D3\u10D4\u10DC\u10D0\u10D3 \u10D3\u10D8\u10D3\u10D8\u10D0, \u10E0\u10D0\u10DB\u10D3\u10D4\u10DC\u10D0\u10D3 \u10D3\u10D8\u10D3\u10D8\u10D0 \u10DB\u10D8\u10E1\u10D8 \u10DB\u10D8\u10D6\u10D0\u10DC\u10D8.\u201C",
