    "content": "\u10D3\u10D8\u10DA\u10D8\u10D7 \u10DE\u10D8\u10E0\u10D5\u10D4\u10DA\u10D8 30 \u10EC\u10E3\u10D7\u10D8 \u10E1\u10DD\u10EA\u10D8\u10D0\u10DA\u10E3\u10E0\u10D8 \u10E5\u10E1\u10D4\u10DA\u10D4\u10D1\u10D8 \u10D0\u10E0 \u10D2\u10D0\u10EE\u10E1\u10DC\u10D0.",
