    "content": "\u201E\u10E1\u10D8\u10D1\u10E0\u10EB\u10DC\u10D4 \u10D8\u10EC\u10E7\u10D4\u10D1\u10D0 \u10D8\u10DB\u10D8\u10E1 \u10D0\u10E6\u10D8\u10D0\u10E0\u10D4\u10D1\u10D8\u10D7, \u10E0\u10DD\u10DB \u10E7\u10D5\u10D4\u10DA\u10D0\u10E4\u10D4\u10E0\u10D8 \u10D0\u10E0 \u10D8\u10EA\u10D8.\u201C \u2014 \u10E1\u10DD\u10D9\u10E0\u10D0\u10E2\u10D4",
