    "content": "\u10DC\u10D8\u10D5\u10D7\u10D8\u10E1 \u10E7\u10D8\u10D3\u10D5\u10D0\u10DB\u10D3\u10D4 24 \u10E1\u10D0\u10D0\u10D7\u10D8 \u10D3\u10D0\u10D4\u10DA\u10DD\u10D3\u10D4 \u2014 \u10EE\u10E8\u10D8\u10E0\u10D0\u10D3 \u10E1\u10E3\u10E0\u10D5\u10D8\u10DA\u10D8 \u10D7\u10D0\u10D5\u10D8\u10E1\u10D8\u10D7 \u10E5\u10E0\u10D4\u10D1\u10D0.",
