    "content": "\u201E\u10E8\u10D8\u10E8\u10D8 \u10EE\u10E8\u10D8\u10E0\u10D0\u10D3 \u10E3\u10E4\u10E0\u10DD \u10D3\u10D8\u10D3\u10D8\u10D0, \u10D5\u10D8\u10D3\u10E0\u10D4 \u10D7\u10D0\u10D5\u10D0\u10D3 \u10E1\u10D0\u10E4\u10E0\u10D7\u10EE\u10D4.\u201C \u2014 \u10E1\u10D4\u10DC\u10D4\u10D9\u10D0",
