    "content": "\u10E2\u10D4\u10DA\u10D4\u10E4\u10DD\u10DC\u10E8\u10D8 \u10E8\u10D4\u10E5\u10DB\u10D4\u10DC\u10D8 \u201C\u10E1\u10D0\u10E7\u10D8\u10D3\u10DA\u10D4\u10D1\u10D8\u10E1\u201D \u10E1\u10D0\u10D4\u10E0\u10D7\u10DD \u10E1\u10D8\u10D0 \u2014 \u10E0\u10DD\u10EA\u10D0 \u10E0\u10D0\u10DB\u10D4 \u10D2\u10D0\u10D2\u10D0\u10EE\u10E1\u10D4\u10DC\u10D3\u10D4\u10D1\u10D0, \u10DB\u10D0\u10E8\u10D8\u10DC\u10D5\u10D4 \u10E9\u10D0\u10EC\u10D4\u10E0\u10D4.",
