    "content": "\u10D5\u10D0\u10E0\u10EF\u10D8\u10E8\u10D8 \u10D3\u10D0\u10D8\u10EC\u10E7\u10D4 10 \u10EC\u10E3\u10D7\u10D8\u10D7 \u2014 \u10DB\u10D7\u10D0\u10D5\u10D0\u10E0\u10D8\u10D0 \u10E1\u10D8\u10E1\u10E2\u10D4\u10DB\u10D0\u10E2\u10E3\u10E0\u10DD\u10D1\u10D0, \u10D0\u10E0\u10D0 \u10D8\u10D3\u10D4\u10D0\u10DA\u10E3\u10E0\u10DD\u10D1\u10D0.",
