    "content": "\u10DB\u10D0\u10DC\u10E5\u10D0\u10DC\u10D0\u10E8\u10D8 \u10DE\u10D8\u10E0\u10D5\u10D4\u10DA\u10D0\u10D3\u10D8 \u10D3\u10D0\u10EE\u10DB\u10D0\u10E0\u10D4\u10D1\u10D8\u10E1 \u10DC\u10D0\u10D9\u10E0\u10D4\u10D1\u10D8 \u10D8\u10E5\u10DD\u10DC\u10D8\u10D4.",
