    "content": "\u10EB\u10E0\u10D0\u10D5\u10D8\u10E1 \u10EE\u10D0\u10DC\u10D2\u10E0\u10EB\u10DA\u10D8\u10D5\u10D0\u10D3 \u10E3\u10E5\u10DB\u10D0\u10D3 \u10DB\u10E3\u10E8\u10D0\u10DD\u10D1\u10D0 \u10E1\u10D0\u10ED\u10D8\u10E0\u10DD\u10D4\u10D1\u10D8\u10E1 \u10D2\u10D0\u10E0\u10D4\u10E8\u10D4 \u10D0\u10E0 \u10D0\u10E0\u10D8\u10E1 \u10D4\u10D9\u10DD\u10DC\u10DD\u10DB\u10D8\u10E3\u10E0\u10D8.",
